def main() -> None:
    raw = base64.b64decode("".join(BUNDLE_B64.split()))
    actual = hashlib.sha256(raw).hexdigest()
    if actual != EXPECTED_SHA256:
        raise SystemExit(f"Embedded site bundle checksum mismatch: {actual}")
    out = Path("dist")
    if out.exists():
        shutil.rmtree(out)
    out.mkdir(parents=True, exist_ok=True)
    with zipfile.ZipFile(io.BytesIO(raw), "r") as zf:
        zf.extractall(out)
    count = sum(1 for p in out.rglob("*") if p.is_file())
    print(f"Links site v{VERSION} expanded to {out} ({count} files).")


if __name__ == "__main__":
    main()
